SET XACT_ABORT ON;BEGIN TRAN;
IF NOT EXISTS(SELECT 1 FROM dbo.OperationTypes WHERE OperationTypeCode='TRANSFER') BEGIN IF COL_LENGTH('dbo.OperationTypes','operationCode') IS NULL EXEC(N'INSERT dbo.OperationTypes(OperationTypeId,OperationTypeCode,OperationTypeNameEn,IsActive) VALUES(''00000000-0000-0000-0000-000000000001'',''TRANSFER'',''Transfer'',1)'); ELSE EXEC(N'INSERT dbo.OperationTypes(OperationTypeId,operationCode,operationNameAr,OperationTypeNameEn,OperationTypeCode,isActive,isDeleted,createdTime,createdBy) VALUES(''00000000-0000-0000-0000-000000000001'',1,N''Transfer'',''Transfer'',''TRANSFER'',1,0,SYSUTCDATETIME(),''deployment'')');END;
IF NOT EXISTS(SELECT 1 FROM dbo.UsageTypes WHERE UsageTypeCode='BENEFICIARY') BEGIN IF COL_LENGTH('dbo.UsageTypes','typeCode') IS NULL EXEC(N'INSERT dbo.UsageTypes(UsageTypeId,UsageTypeCode,UsageTypeNameEn,IsActive) VALUES(''00000000-0000-0000-0000-000000000001'',''BENEFICIARY'',''Beneficiary payment'',1)'); ELSE EXEC(N'INSERT dbo.UsageTypes(UsageTypeId,typeCode,typeNameAr,UsageTypeNameEn,UsageTypeCode,isActive,isDeleted,createdTime,createdBy) VALUES(''00000000-0000-0000-0000-000000000001'',1,N''Beneficiary payment'',''Beneficiary payment'',''BENEFICIARY'',1,0,SYSUTCDATETIME(),''deployment'')');END;
IF NOT EXISTS(SELECT 1 FROM dbo.ResourceTypes WHERE ResourceTypeCode='BANK') INSERT dbo.ResourceTypes(ResourceTypeId,ResourceTypeCode,ResourceTypeNameEn,ResourceTypeNameAr,IsActive,CreatedBy) VALUES('00000000-0000-0000-0000-000000000001','BANK','Bank funding',N'Bank funding',1,'deployment');
IF NOT EXISTS(SELECT 1 FROM dbo.Banks WHERE BankCode='DEFAULT') INSERT dbo.Banks(BankId,BankCode,BankNameEn,ShortName,CreatedBy) VALUES('00000000-0000-0000-0000-000000000001','DEFAULT','Default remitting bank','DEFAULT','deployment');
COMMIT;
